// Event sourcing: all billing state changes are recorded as immutable events.
// "tenant" here always means a customer account, never a database schema.

export interface InvoiceCreated {
  readonly type: "InvoiceCreated";
  readonly occurredAt: string; // ISO 8601
  readonly tenantId: string; // customer account identifier
  readonly invoiceId: string;
  readonly amount: number; // minor units, …
